INSERT INTO projects (id, name, investor, location, description, total_units, status, created_at) VALUES ('6e98bb99-ef66-41e9-a652-e3192c251d8d', 'Sunny Line', 'Sunny Line DOO', 'Klisa, Novi Sad', 'SUNNY LINE - jedinstven stambeni kompleks koji se sastoji od 3 nezavisne ville na prestižnoj lokaciji Klise, u Ulici Đakona Avakuma. Svaka vila je nezavisan objekat. Ukupno 16 stanova različitih veličina. Modern arhitektonski pristup. Miran deo grada okružen zelenilom. Odlična povezanost sa centrom grada. Planiran završetak: maj 2027 (±60 dana). Početak gradnje: maj 2026.', 16, 'U izgradnji', '2026-06-02T10:47:55.503Z');
